`timescale 1ns/1ps
module tb_tessera_vec_system;
localparam N=4,OW=3,TW=8,DW=16,CW=2,D=4; logic clk=0,rst_n=0,completion_valid,completion_ready=1; logic [N-1:0] req=0,grant; logic [N*OW-1:0] op_bus=0; logic [N*TW-1:0] tag_bus=0; logic [N*DW-1:0] operand_a_bus=0,operand_b_bus=0; logic [CW-1:0] completion_client; logic [TW-1:0] completion_tag; logic [1:0] completion_status; logic [DW-1:0] completion_result; logic [$clog2(D+1)-1:0] completion_occupancy; integer i; always #5 clk=~clk; tessera_vec_system dut(.*); task tick; begin @(posedge clk); #1; end endtask
initial begin repeat(2) tick(); rst_n=1; tick(); for(i=0;i<N;i=i+1) begin op_bus[i*OW+:OW]=0; tag_bus[i*TW+:TW]=8'h30+i; operand_a_bus[i*DW+:DW]=i+10; operand_b_bus[i*DW+:DW]=i+20; end req=4'b1111; for(i=0;i<4;i=i+1) begin while(!grant) tick(); tick(); end req=0; for(i=0;i<4;i=i+1) begin while(!completion_valid) tick(); #1; if(completion_client!==i[CW-1:0]) $fatal(1,"client ordering"); if(completion_tag!==(8'h30+i)) $fatal(1,"tag mismatch"); if(completion_result!==(30+2*i)) $fatal(1,"real add result mismatch got=%0d",completion_result); if(completion_status!==0) $fatal(1,"status mismatch"); tick(); end $display("PASS: multi-client real vector execution and tagged results"); $finish; end
endmodule
